  pubFailed: { en: "The server didn't accept this product. Check the details and try again.", hi: "सर्वर ने यह उत्पाद स्वीकार नहीं किया। जानकारी जाँचकर फिर कोशिश करें।", kn: "ಸರ್ವರ್ ಈ ಉತ್ಪನ್ನವನ್ನು ಸ್ವೀಕರಿಸಲಿಲ್ಲ. ವಿವರ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.", ta: "சர்வர் இந்தப் பொருளை ஏற்கவில்லை. விவரங்களைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும்.", te: "సర్వర్ ఈ ఉత్పత్తిని అంగీకరించలేదు. వివరాలు తనిఖీ చేసి మళ్లీ ప్రయత్నించండి.", bn: "সার্ভার এই পণ্যটি গ্রহণ করেনি। তথ্য যাচাই করে আবার চেষ্টা করুন।", mr: "सर्व्हरने हे उत्पादन स्वीकारले नाही. तपशील तपासून पुन्हा प्रयत्न करा.", gu: "સર્વરે આ ઉત્પાદન સ્વીકાર્યું નહીં. વિગતો તપાસી ફરી પ્રયાસ કરો.", or: "ସର୍ଭର ଏହି ଉତ୍ପାଦ ଗ୍ରହଣ କଲା ନାହିଁ। ବିବରଣୀ ଯାଞ୍ଚ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।" },
  pubQueuedTitle: { en: "Waiting to publish", hi: "प्रकाशन की प्रतीक्षा", kn: "ಪ್ರಕಟಣೆಗೆ ಕಾಯುತ್ತಿದೆ", ta: "வெளியிடக் காத்திருக்கிறது", te: "ప్రచురణ కోసం వేచి ఉంది", bn: "প্রকাশের অপেক্ষায়", mr: "प्रकाशनाची वाट पाहत आहे", gu: "પ્રકાશન માટે રાહ", or: "ପ୍ରକାଶ ପାଇଁ ଅପେକ୍ଷା" },
  pubQueued: { en: "You're offline. Your product is saved on this phone and will be published automatically when you're connected.", hi: "आप ऑफ़लाइन हैं। आपका उत्पाद इस फ़ोन पर सहेजा गया है और इंटरनेट मिलते ही अपने आप प्रकाशित हो जाएगा।", kn: "ನೀವು ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿದ್ದೀರಿ. ನಿಮ್ಮ ಉತ್ಪನ್ನ ಈ ಫೋನ್‌ನಲ್ಲಿ ಉಳಿಸಲಾಗಿದೆ, ಸಂಪರ್ಕ ಸಿಕ್ಕಾಗ ತಾನಾಗಿ ಪ್ರಕಟವಾಗುತ್ತದೆ.", ta: "நீங்கள் ஆஃப்லைனில் உள்ளீர்கள். உங்கள் பொருள் இந்த போனில் சேமிக்கப்பட்டது; இணைப்பு கிடைத்ததும் தானாக வெளியிடப்படும்.", te: "మీరు ఆఫ్‌లైన్‌లో ఉన్నారు. మీ ఉత్పత్తి ఈ ఫోన్‌లో సేవ్ అయింది, కనెక్ట్ అయినప్పుడు స్వయంగా ప్రచురించబడుతుంది.", bn: "আপনি অফলাইনে। আপনার পণ্য এই ফোনে সংরক্ষিত, সংযোগ পেলেই নিজে থেকে প্রকাশিত হবে।", mr: "तुम्ही ऑफलाइन आहात. तुमचे उत्पादन या फोनवर जतन केले आहे आणि कनेक्शन मिळताच आपोआप प्रकाशित होईल.", gu: "તમે ઑફલાઇન છો. તમારું ઉત્પાદન આ ફોન પર સચવાયું છે અને કનેક્ટ થતાં આપમેળે પ્રકાશિત થશે.", or: "ଆପଣ ଅଫଲାଇନ୍ ଅଛନ୍ତି। ଆପଣଙ୍କ ଉତ୍ପାଦ ଏହି ଫୋନ୍‌ରେ ସେଭ୍ ହୋଇଛି ଏବଂ ସଂଯୋଗ ମିଳିଲେ ନିଜେ ପ୍ରକାଶ ହେବ।" },
  pubRetryNow: { en: "Try now", hi: "अभी कोशिश करें", kn: "ಈಗ ಪ್ರಯತ್ನಿಸಿ", ta: "இப்போது முயற்சி", te: "ఇప్పుడు ప్రయత్నించండి", bn: "এখন চেষ্টা করুন", mr: "आता प्रयत्न करा", gu: "હવે પ્રયાસ કરો", or: "ଏବେ ଚେଷ୍ଟା କରନ୍ତୁ" },
  pubWaitingN: { en: "{n} product(s) waiting to publish — they'll go live when you're connected.", hi: "{n} उत्पाद प्रकाशन की प्रतीक्षा में — इंटरनेट मिलते ही लाइव होंगे।", kn: "{n} ಉತ್ಪನ್ನ(ಗಳು) ಪ್ರಕಟಣೆಗೆ ಕಾಯುತ್ತಿವೆ — ಸಂಪರ್ಕ ಸಿಕ್ಕಾಗ ಲೈವ್ ಆಗುತ್ತವೆ.", ta: "{n} பொருள்(கள்) வெளியிடக் காத்திருக்கின்றன — இணைப்பு கிடைத்ததும் நேரலைக்கு வரும்.", te: "{n} ఉత్పత్తి(లు) ప్రచురణ కోసం వేచి ఉన్నాయి — కనెక్ట్ అయినప్పుడు లైవ్ అవుతాయి.", bn: "{n}টি পণ্য প্রকাশের অপেক্ষায় — সংযোগ পেলেই লাইভ হবে।", mr: "{n} उत्पादन(ने) प्रकाशनाच्या प्रतीक्षेत — कनेक्शन मिळताच लाइव्ह होतील.", gu: "{n} ઉત્પાદન(નો) પ્રકાશનની રાહમાં — કનેક્ટ થતાં લાઇવ થશે.", or: "{n}ଟି ଉତ୍ପାଦ ପ୍ରକାଶ ଅପେକ୍ଷାରେ — ସଂଯୋଗ ମିଳିଲେ ଲାଇଭ୍ ହେବ।" },
  shareCard: { en: "Share product card", hi: "उत्पाद कार्ड साझा करें", kn: "ಉತ್ಪನ್ನ ಕಾರ್ಡ್ ಹಂಚಿಕೊಳ್ಳಿ", ta: "பொருள் அட்டையைப் பகிர்", te: "ఉత్పత్తి కార్డ్ షేర్ చేయండి", bn: "পণ্যের কার্ড শেয়ার করুন", mr: "उत्पादन कार्ड शेअर करा", gu: "ઉત્પાદન કાર્ડ શેર કરો", or: "ଉତ୍ପାଦ କାର୍ଡ ସେୟାର୍ କରନ୍ତୁ" },
  shareCardSub: { en: "A picture with the price and QR code, for WhatsApp and Instagram", hi: "दाम और QR कोड वाली तस्वीर, WhatsApp और Instagram के लिए", kn: "ಬೆಲೆ ಮತ್ತು QR ಕೋಡ್ ಇರುವ ಚಿತ್ರ, WhatsApp ಮತ್ತು Instagram ಗಾಗಿ", ta: "விலை மற்றும் QR குறியீட்டுடன் படம், WhatsApp, Instagram-க்கு", te: "ధర, QR కోడ్ ఉన్న చిత్రం, WhatsApp మరియు Instagram కోసం", bn: "দাম ও QR কোডসহ ছবি, WhatsApp ও Instagram-এর জন্য", mr: "किंमत आणि QR कोड असलेले चित्र, WhatsApp आणि Instagram साठी", gu: "કિંમત અને QR કોડવાળું ચિત્ર, WhatsApp અને Instagram માટે", or: "ମୂଲ୍ୟ ଓ QR କୋଡ୍ ଥିବା ଛବି, WhatsApp ଓ Instagram ପାଇଁ" },

